mapper.select:
select id, title, author, cover_url as coverUrl, like_count as likeCount, comment_count as commentCount, create_time as createTime from notes where status = 'active'
and ( title like concat('%', #{keyword}, '%') or content_markdown like concat('%', #{keyword}, '%') )
order by create_time desc limit #{offset}, #{limit}

mapper.update:
update notes
set comment_count = comment_count + 1, update_time = NOW()
where id = #{noteId}
